```csharp
using UnityEngine;

public static class DistanceToScale
{
    /// <summary>
    /// Maps a distance between 200 and 300 to a value between 0 and 1.
    /// </summary>
    public static float DistanceToScale(float distance)
    {
        if (distance < 200)
            return 0.0f;
        if (distance > 300)
            return 1.0f;

        // Linear interpolation between 200 and 300
        return 1.0f - (distance - 200) / (300 - 200);
    }
}
