Here is a small, functional React component that implements Drag and Drop between two divs using the native HTML5 Drag and Drop API.

This solution uses `onDragOver` and `onDrop` events to handle the interaction.

```jsx
import React, { useState } from 'react';

const DropItem = ({ item, onDrop, onDragOver }) => {
  return (
    <div
      draggable="true"
      onDragOver={onDragOver}
      onDrop={onDrop}
      className="drop-item"
    >
      {item}
    </div>
  );
};

const DropContainer = ({ items, onDrop, onDragOver }) => {
  return (
    <div
      onDragOver={onDragOver}
      onDrop={onDrop}
      className="drop-container"
    >
      {items.map((item, index) => (
        <DropItem key={index} item={item} onDrop={onDrop} onDragOver={onDragOver} />
      ))}
    </div>
  );
};

export default function DropAndDropDemo() {
  const [items, setItems] = useState([
    { id: 1, text: 'Item 1' },
    { id: 2, text: 'Item 2' },
    { id: 3, text: 'Item 3' },
  ]);

  const handleDrop = (e) => {
    e.preventDefault();
    const target = e.target;
    const dropIndex = target.children.length - 1;
    setItems((prevItems) => {
      const newItems = [...prevItems];
      newItems.splice(dropIndex, 1);
      newItems.push({ id: Date.now(), text: 'New Item' });
      return newItems;
    });
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  return (
    <div className="drop-container">
      <DropContainer items={items} onDrop={handleDrop} onDragOver={handleDragOver} />
    </div>
  );
}
```

### Key Features of this snippet:
*   **Native API:** Uses `onDragOver` and `onDrop` to prevent the browser from blocking the drop.
*   **State Management:** Uses `useState` to track the array of items and updates it in real-time.
*   **Draggable:** The `draggable="true"` attribute ensures the items can be moved.
*   **Responsive:** The container is styled to look like a drop zone.

