#include <iostream>

// Function to calculate the perimeter of a square
int calculateSquarePerimeter(int sideLength) {
    // A square has 4 equal sides
    return 4 * sideLength;
}

// Function to calculate the area of a square
int calculateSquareArea(int sideLength) {
    // A square has 4 equal sides
    return sideLength * sideLength;
}

// Main function to demonstrate the program
int main() {
    int sideLength;

    // Ask the user for the side length of the square
    std::cout << "Enter the side length of the square: ";
    std::cin >> sideLength;

    // Calculate the perimeter
    int perimeter = calculateSquarePerimeter(sideLength);

    // Calculate the area
    int area = calculateSquareArea(sideLength);

    // Display the results
    std::cout << "Perimeter of the square: " << perimeter << " units" << std::endl;
    std::cout << "Area of the square: " << area << " square units" << std::endl;

    return 0;
}
